const BODY_B = BODY_F;

function anatomySVG(id, opts){
  opts = opts||{};
  const W = opts.single ? 108 : 216;
  let s = '<svg viewBox="0 0 '+W+' 236" width="100%" role="img" aria-label="Muscle activation map" style="display:block;max-height:'+(opts.h||250)+'px">';
  const views = opts.single ? [["f",4]] : [["f",0],["b",112]];
  for(const [v,dx] of views){
    s += '<g transform="translate('+dx+',0)">';
    s += '<path d="'+(v==="f"?BODY_F:BODY_B)+'" fill="var(--muscle-base)" opacity="'+(v==="f"?.5:.5)+'"/>';
    s += '<path d="'+(v==="f"?BODY_F:BODY_B)+'" fill="none" stroke="var(--line-hard)" stroke-width=".8"/>';
    for(const mid of MUSCLE_IDS){
      const shapes = GEO[mid] ? GEO[mid][v] : null;
      if(!shapes || !shapes.length) continue;
      s += '<g class="mus" data-m="'+mid+'" data-view="'+v+'" fill="var(--muscle-base)" opacity=".92">';
      for(const sh of shapes){
        s += sh.t==="e"
          ? '<ellipse cx="'+sh.cx+'" cy="'+sh.cy+'" rx="'+sh.rx+'" ry="'+sh.ry+'" transform="rotate('+sh.rot+' '+sh.cx+' '+sh.cy+')"/>'
          : '<path d="'+sh.d+'"/>';
      }
      s += '</g>';
    }
    s += '<text x="50" y="234" text-anchor="middle" font-family="var(--f-mono)" font-size="7" letter-spacing="1.6" fill="var(--ink-3)">'+(v==="f"?"FRONT":"BACK")+'</text>';
    s += '</g>';
  }
  s += '</svg>';
  return '<div id="'+id+'">'+s+'</div>';
}

/* paint activation: map muscleId -> 0..1 */
function paintAnatomy(root, act){
  if(!root) return;
  root.querySelectorAll(".mus").forEach(g=>{
    const v = act[g.dataset.m] || 0;
    if(v <= 0){ g.setAttribute("fill","var(--muscle-base)"); g.setAttribute("opacity",".92"); return; }
    const c = v >= .75 ? "var(--accent)" : v >= .4 ? "color-mix(in srgb, var(--accent) 68%, var(--p15))" : "var(--p15)";
    g.setAttribute("fill", c);
    g.setAttribute("opacity", String(0.55 + 0.45*Math.min(1,v)));
    g.style.transition = "fill .5s ease, opacity .5s ease";
  });
}

