const XMAP = Object.fromEntries(X.map(x=>[x.id,x]));
/* ------------------------------------------------------------------ focus */
const FOCUS = {
  full:      {n:"Full body",     m:MUSCLE_IDS.slice()},
  push:      {n:"Push",          m:["chest","delt_f","delt_s","triceps"]},
  pull:      {n:"Pull",          m:["lats","upperback","biceps","delt_r","forearms"]},
  chest:     {n:"Chest",         m:["chest","delt_f","triceps"]},
  back:      {n:"Back",          m:["lats","upperback","traps","delt_r","lowerback"]},
  shoulders: {n:"Shoulders",     m:["delt_f","delt_s","delt_r","traps"]},
  arms:      {n:"Arms",          m:["biceps","triceps","forearms"]},
  legs:      {n:"Legs",          m:["quads","hams","glutes","calves","adductors"]},
  posterior: {n:"Posterior chain",m:["glutes","hams","lowerback","upperback","traps","lats"]},
  core:      {n:"Core",          m:["abs","obliques","hipflex"]}
};

/* ---------------------------------------------------------------- presets */
const PRESETS = {
  easy:   {n:"Easy Day",  c:"var(--p10)", count:4, effort:1, focus:["full"], comps:1,
           cardio:true,  cstyle:"steady",
           d:"Move, don't maul. Full body, low fatigue, easy conditioning to finish."},
  medium: {n:"Medium Day",c:"var(--p15)", count:5, effort:2, focus:["full"], comps:2,
           cardio:false, cstyle:"intervals",
           d:"The default. Two compounds, broad coverage, in and out in about an hour."},
  killer: {n:"Killer",    c:"var(--p25)", count:7, effort:4, focus:["full"], comps:3,
           cardio:true,  cstyle:"finisher", failure:true,
           d:"Heavy compounds, real volume, a finisher that hurts. Plan your next day around it."},
  cardio: {n:"Cardio",    c:"var(--p20)", count:3, effort:2, focus:["legs","core"], comps:1,
           cardio:true,  cstyle:"intervals",
           d:"Conditioning is the session. A short strength primer, then the engine work."}
};

/* -------------------------------------------------------------- schemes */
const EFFORT_N = ["","Deload","Medium","Hard","Killer"];
const EFFORT_NOTE = [ "",
  "Leave three reps in the tank on everything. This should feel like it woke you up, not wrecked you.",
  "Two reps in reserve. The last set of each movement should be work, not a fight.",
  "One rep in reserve on compounds. Accessories go close to the edge.",
  "Compounds are heavy and slow. Accessories go to failure. Eat and sleep accordingly."];
const SCHEME = {
  comp:[null,{s:3,r:"8",rest:90, rpe:"RPE 6", tempo:"3-0-1"},
             {s:4,r:"6–8",rest:120,rpe:"RPE 7", tempo:"2-1-1"},
             {s:5,r:"5",rest:150,rpe:"RPE 8", tempo:"2-1-X"},
             {s:5,r:"3–5",rest:180,rpe:"RPE 9", tempo:"2-1-X", note:"Add a back-off set at 60% for 8."}],
  acc: [null,{s:2,r:"12",rest:60, rpe:"RPE 6", tempo:"2-0-2"},
             {s:3,r:"10–12",rest:75,rpe:"RPE 7", tempo:"2-0-2"},
             {s:4,r:"8–10",rest:90, rpe:"RPE 8", tempo:"3-0-1"},
             {s:4,r:"8–10",rest:75, rpe:"RPE 9", tempo:"3-0-1", note:"Take the last set to technical failure."}],
  iso: [null,{s:2,r:"15",rest:45, rpe:"RPE 6", tempo:"2-0-2"},
             {s:3,r:"12–15",rest:60,rpe:"RPE 8", tempo:"2-1-2"},
             {s:3,r:"12–15",rest:45,rpe:"RPE 9", tempo:"3-1-1", note:"Drop set on the last one."},
             {s:4,r:"12–15",rest:45,rpe:"RPE 10",tempo:"3-1-1", note:"Drop set on the last two."}],
  core:[null,{s:2,r:"12",rest:45, rpe:"Controlled", tempo:"slow"},
             {s:3,r:"12–15",rest:45,rpe:"Controlled",tempo:"slow"},
             {s:3,r:"15–20",rest:40,rpe:"Hard",tempo:"slow"},
             {s:4,r:"15–20",rest:30,rpe:"Hard",tempo:"slow", note:"Minimal rest — treat it as a finisher."}]
};
const CORE_SEC = [null,{s:2,r:"30 sec"},{s:3,r:"40 sec"},{s:3,r:"50 sec"},{s:4,r:"60 sec"}];

/* --------------------------------------------------------- cardio blocks */
const CSTYLE = {
  intervals:{n:"Intervals", d:"Repeats near your limit with real recovery between."},
  steady:   {n:"Steady state", d:"One sustained conversational effort."},
  finisher: {n:"Finisher",  d:"Short, brutal, and over before you can negotiate."},
  treadmill:{n:"Treadmill", d:"Belt on, minutes chosen by you, head down."}
};
function buildCardio(avail, style, effort, seed, tmins){
  /* Treadmill is its own contract: the person picked the machine and the
     minutes, so nothing here second-guesses either. It also skips the kit
     filter on purpose — choosing the treadmill IS declaring access to one,
     the same way picking Public Gym declares the gym. */
  if(style === "treadmill"){
    const m = Math.max(5, Math.min(120, tmins || 20));
    return {x: XMAP.run_steady, style, styleName: CSTYLE.treadmill.n, styleDesc: CSTYLE.treadmill.d,
      segs: [
        {k:"Warm-up",   v:"3 min walk, building to an easy jog"},
        {k:"Main",      v:m + " min at the pace you came for — hold it honest"},
        {k:"Cool-down", v:"2 min walk before you step off"}],
      mins: m + 5};
  }
  const opts = X.filter(x=>x.cls==="cardio" && x.eq.every(t=>avail.includes(t)));
  if(!opts.length) return null;
  const prefer = {intervals:["row_int","bike_int","run_int","kbcondition","rope","burpee","shadowrun"],
                  steady:["run_steady","bike_int","row_int","rope","shadowrun"],
                  finisher:["burpee","sledpush","kbcondition","rope","bike_int","row_int","mountainclimb","shadowrun"]}[style];
  let pick = null;
  for(const id of prefer){ const f = opts.find(o=>o.id===id); if(f){ pick = f; break; } }
  if(!pick) pick = opts[Math.floor(seed()*opts.length)];

  const segs = [];
  let mins;
  if(style === "steady"){
    mins = [0,22,28,34,40][effort];
    segs.push({k:"Warm-up",  v:"5 min easy, nose breathing only"});
    segs.push({k:"Main",     v:mins+" min at a pace you could hold a conversation through"});
    segs.push({k:"Cool-down",v:"3 min walk, then two minutes of long exhales"});
    mins += 8;
  }else if(style === "intervals"){
    const rounds = [0,5,8,10,12][effort];
    const work   = [0,"30 sec","40 sec","45 sec","60 sec"][effort];
    const rest   = [0,"90 sec","75 sec","60 sec","60 sec"][effort];
    segs.push({k:"Warm-up", v:"5 min building from easy to moderate"});
    segs.push({k:"Work",    v:rounds+" × "+work+" hard — 8 out of 10, you can say a word but not a sentence"});
    segs.push({k:"Recover", v:rest+" easy between rounds. Stay moving."});
    segs.push({k:"Cool-down",v:"4 min easy spin or walk"});
    mins = 9 + Math.round(rounds * (parseInt(work)+parseInt(rest))/60);
  }else{
    const rounds = [0,3,4,5,6][effort];
    segs.push({k:"Format", v:rounds+" rounds, straight through, no music breaks"});
    segs.push({k:"Round",  v:"40 sec all-out "+pick.n.toLowerCase()+" / 20 sec on the floor"});
    segs.push({k:"Then",   v:"30 sec plank hold before the next round starts"});
    segs.push({k:"Rule",   v:"If your form breaks, stop the round. Volume is not the point here."});
    mins = rounds*2 + 4;
  }
  return {x:pick, style, styleName:CSTYLE[style].n, styleDesc:CSTYLE[style].d, segs, mins};
}

/* ------------------------------------------------------------- generator */
function mulberry(a){ return function(){ a|=0; a=a+0x6D2B79F5|0; let t=Math.imul(a^a>>>15,1|a);
  t=t+Math.imul(t^t>>>7,61|t)^t; return ((t^t>>>14)>>>0)/4294967296; }; }

const ORDER = {comp:0, acc:1, iso:2, core:3, cardio:4};
const PAT_ORDER = {squat:0,hinge:0,push_h:1,pull_h:1,push_v:2,pull_v:2,lunge:3,hip:3,
                   iso_delt:5,iso_arm:5,iso_leg:5,carry:6,core:7,cardio:8};
/* squat and hinge legitimately map to 0 — never fall back with `||` */
const patOrd = p => (p in PAT_ORDER) ? PAT_ORDER[p] : 9;

function activationOf(list){
  const act = {};
  for(const m of MUSCLE_IDS) act[m]=0;
  for(const item of list){
    const x = item.x || item;
    for(const m of (x.pri||[])) act[m] = Math.min(1.6, act[m] + 1.0);
    for(const m of (x.sec||[])) act[m] = Math.min(1.6, act[m] + 0.45);
  }
  const out = {};
  for(const m of MUSCLE_IDS) out[m] = Math.min(1, act[m]);
  return out;
}
function coverageOf(act, scope){
  const ids = scope ? MUSCLE_IDS.filter(m => scope.has(m)) : MUSCLE_IDS;
  if(!ids.length) return 0;
  let s=0; for(const m of ids) s += Math.min(1, act[m]);
  return Math.round(100 * s / ids.length);
}

/* Rolling read of what recent sessions have actually trained. Muscles that keep
   getting skipped build up a debt, and the generator pays it down. */
/* Which lifts you have actually done lately, 1 for the last session fading to
   0 six back. The generator already refuses to repeat a movement pattern inside
   one session; this is the same instinct stretched across days. Without it a
   big catalogue still collapses onto the same dozen favourites, because the
   coverage maths scores an exercise the same whether or not you did it
   yesterday. Gated with the rest of the history-aware programming. */
function recentLifts(){
  if(!limitsOf().adaptive) return {};
  const recent = (state.history || []).slice(0, 6), seen = {};
  recent.forEach((h, i) => {
    const w = 1 - i / (recent.length + 1);
    (h.mids || []).forEach(id => { seen[id] = Math.max(seen[id] || 0, w); });
  });
  return seen;
}

function muscleDebt(){
  if(!limitsOf().adaptive){
    const debt = {}; MUSCLE_IDS.forEach(m => debt[m] = 0);
    return {debt, ready:false};
  }
  const recent = (state.history || []).slice(0, 14);
  const tally = {}; MUSCLE_IDS.forEach(m => tally[m] = 0);
  let any = false;
  recent.forEach((h, i) => {
    const w = 1 - i / (recent.length + 3);          /* the last week counts most */
    (h.mids || []).forEach(id => {
      const x = XMAP[id]; if(!x) return;
      any = true;
      x.pri.forEach(m => { if(m in tally) tally[m] += 1.0 * w; });
      x.sec.forEach(m => { if(m in tally) tally[m] += 0.45 * w; });
    });
  });
  const debt = {}; MUSCLE_IDS.forEach(m => debt[m] = 0);
  if(!any) return {debt, ready:false};
  const peak = Math.max(1, ...MUSCLE_IDS.map(m => tally[m]));
  MUSCLE_IDS.forEach(m => { debt[m] = 1 - Math.min(1, tally[m] / (peak * 0.55)); });
  return {debt, ready:true};
}
function neglected(n){
  const {debt, ready} = muscleDebt();
  if(!ready) return [];
  return MUSCLE_IDS.filter(m => debt[m] > 0.7).sort((a,b) => debt[b] - debt[a]).slice(0, n || 3);
}

function generate(cfg){
  cfg.count = Math.min(cfg.count, limitsOf().moves);
  const rnd = mulberry(cfg.seed);
  const avail = availFor(cfg.loc).slice();
  const lim = state.limits || [];
  const has = x => x.eq.every(t => avail.includes(t)) && !blockedBy(x, lim);
  /* custom:true movements came off a video someone uploaded: they belong to
     that one session and never enter the generator's pool */
  const pool = X.filter(x => x.cls !== "cardio" && !x.custom && has(x));

  const targets = new Set();
  const focusKeys = cfg.focus.length ? cfg.focus : ["full"];
  focusKeys.forEach(k => FOCUS[k].m.forEach(m => targets.add(m)));
  const wholeBody = focusKeys.includes("full");
  /* On a focused day the pool widens in tiers rather than falling back to the
     whole library — asking for 10 arm movements must not hand you leg day. */
  const tier1 = x => x.pat === "core" || x.pri.filter(m => targets.has(m)).length >= Math.ceil(x.pri.length / 2);
  const tier2 = x => x.pri.some(m => targets.has(m));
  let usePool = pool;
  if(!wholeBody){
    usePool = pool.filter(tier1);
    /* one widening step only. Beyond that the movements stop being on-topic,
       so the sheet gets shorter rather than wrong — see `trimmed`. */
    if(usePool.length < cfg.count) usePool = pool.filter(x => tier1(x) || tier2(x));
  }
  /* if the focus genuinely cannot fill the sheet, train less rather than train wrong */
  const trimmedTo = Math.min(cfg.count, Math.max(1, usePool.length));

  const {debt} = muscleDebt();
  const fresh = recentLifts();
  const picked = [];
  const usedArch = new Set();
  const patCount = {};
  const act = {}; MUSCLE_IDS.forEach(m => act[m] = 0);

  const addPick = (x, reason) => {
    picked.push({x, reason});
    usedArch.add(x.arch);
    patCount[x.pat] = (patCount[x.pat]||0) + 1;
    for(const m of x.pri) act[m] = Math.min(1.6, act[m] + 1.0);
    for(const m of x.sec) act[m] = Math.min(1.6, act[m] + 0.45);
  };
  const newlyCovered = x => {
    const got = [];
    for(const m of x.pri) if(act[m] < 0.5) got.push(m);
    if(got.length < 2) for(const m of x.sec) if(act[m] < 0.25 && got.length < 3) got.push(m);
    return got;
  };

  /* 1 — the compounds the lifter asked for, in the order the body prefers them.
     Cardio-class lifts (a few, like battle rope slams, are named in ASK_LIFTS
     so "battle ropes" is heard at all) have no SCHEME entry — they belong in
     the cardio block, not the prescribed list, so they're excluded here the
     same way the pool and swap already exclude cardio. */
  const chosen = cfg.compounds.map(id => XMAP[id]).filter(x => x && x.cls !== "cardio" && !x.custom && has(x))
                  .sort((a,b) => patOrd(a.pat) - patOrd(b.pat));
  for(const x of chosen){
    if(picked.length >= cfg.count) break;
    const got = newlyCovered(x);
    addPick(x, got.length ? "You picked it. Opens the session while you're freshest, and it brings "+musList(got)+" along with it."
                          : "You picked it. Slotted first, while you're freshest.");
  }

  /* 2 — greedy coverage fill */
  const half = Math.max(1, Math.ceil(trimmedTo * 0.45));
  while(picked.length < trimmedTo){
    let best = null, bestScore = -1e9, bestGot = null;
    for(const x of usePool){
      if(picked.some(pk => pk.x.id === x.id)) continue;
      let s = 0;
      const off = wholeBody ? 3.2 : 0.5;
      for(const m of x.pri){
        s += (targets.has(m) ? 11 : off) * (1 - Math.min(1, act[m]));
        s += (debt[m] || 0) * 4.5 * (1 - Math.min(1, act[m]));   /* pay down what's been skipped */
        if(!wholeBody && !targets.has(m)) s -= 5.5;    /* off-target mass costs you the slot */
      }
      for(const m of x.sec) s += (targets.has(m) ? 4.4 : off*0.4) * (1 - Math.min(1, act[m]));
      s -= (patCount[x.pat]||0) * 8;
      if(usedArch.has(x.arch)) s -= 5;
      /* compounds early, isolation late */
      if(x.cls === "comp") s += picked.length < half ? 5.5 : -5;
      if(x.cls === "iso")  s += picked.length >= half ? 2.5 : -3.5;
      if(x.cls === "core") s += picked.length >= cfg.count - 2 ? 4 : -6;
      /* effort shapes the mix */
      if(cfg.effort >= 3 && x.cls === "comp") s += 3;
      if(cfg.effort <= 1 && x.cls === "comp") s -= 3;
      if(cfg.effort <= 1 && x.pat === "core") s += 1.5;
      if(cfg.cardioOn && x.fin) s -= 4;
      if(x.uni) s += 1.2;                 /* unilateral work earns its slot */
      s -= (fresh[x.id] || 0) * 7;        /* did it lately — let something else in */
      s += rnd() * 5.5;                   /* variety between rolls */
      if(s > bestScore){ bestScore = s; best = x; bestGot = newlyCovered(x); }
    }
    if(!best) break;
    addPick(best, bestGot.length
      ? "Slotted to pick up "+musList(bestGot)+" — nothing before it in this session covers that."
      : "Adds volume to muscles already in play without repeating a movement pattern.");
  }

  /* 3 — order the sheet the way you should actually train it */
  picked.sort((a,b) => (ORDER[a.x.cls] - ORDER[b.x.cls]) ||
                       (patOrd(a.x.pat) - patOrd(b.x.pat)));

  /* 4 — prescription */
  const moves = picked.map((pk, i) => {
    const x = pk.x;
    const sec = x.unit === "sec";
    const base = sec ? CORE_SEC[cfg.effort] : SCHEME[x.cls][cfg.effort];
    const sch = Object.assign({}, SCHEME[x.cls][cfg.effort], base);
    return {
      i:i+1, id:x.id, x, reason:pk.reason,
      sets:sch.s, reps:sch.r, rest:sch.rest, rpe:sch.rpe, tempo:sch.tempo, note:sch.note,
      unit:x.unit||"reps", each:!!x.uni,
      /* to-failure belongs on isolation and accessory work, not heavy compounds */
      failure: !!cfg.failureOn && (x.cls === "iso" || x.cls === "acc") && x.unit !== "sec",
      doneSets:[], weight:"", claimed:false
    };
  });

  const cardio = cfg.cardioOn ? buildCardio(avail, cfg.cstyle, cfg.effort, rnd, cfg.tmins) : null;
  const all = cardio ? moves.concat([{x:cardio.x}]) : moves;
  const actMap = activationOf(all);
  const cov = coverageOf(actMap, wholeBody ? null : targets);

  let mins = 8;
  for(const m of moves){
    const rp = parseInt(m.reps) || 12;
    const work = m.unit === "sec" ? rp : rp * 3.5 * (m.each ? 2 : 1);
    mins += m.sets * (work + m.rest) / 60;
  }
  if(cardio) mins += cardio.mins;

  return {
    id: "s"+Date.now(),
    date: new Date().toISOString(),
    cfg, moves, cardio,
    act: actMap, coverage: cov,
    minutes: Math.round(mins),
    title: sessionTitle(cfg, moves),
    trimmed: cfg.count - moves.length,
    caughtUp: picked.map(pk => pk.x).reduce((a2,x) => a2.concat(x.pri.filter(m => (debt[m]||0) > 0.7)), [])
                .filter((v,i,arr) => arr.indexOf(v) === i).slice(0,4),
    xp: 0
  };
}
function musList(ids){
  const names = ids.map(m => M[m].n.toLowerCase());
  if(names.length === 1) return names[0];
  if(names.length === 2) return names[0]+" and "+names[1];
  return names.slice(0,-1).join(", ")+" and "+names[names.length-1];
}
function sessionTitle(cfg, moves){
  const f = cfg.focus.length ? cfg.focus : ["full"];
  if(f.length === 1 && f[0] === "full"){
    const pats = new Set(moves.map(m => m.x.pat));
    if(pats.has("squat") && pats.has("push_h") && pats.has("pull_h")) return "Full Body";
    return "Full Body";
  }
  return f.map(k => FOCUS[k].n).join(" + ");
}

/* ------------------------------------------------------------ points/rank */
const RANKS = [
  {xp:0,     n:"Empty Bar"},   {xp:900,   n:"Quarter"},
  {xp:2400,  n:"One Plate"},   {xp:5200,  n:"Two Plates"},
  {xp:9800,  n:"Three Plates"},{xp:17000, n:"Four Plates"},
  {xp:28000, n:"Five Plates"}, {xp:44000, n:"Cast Iron"}
];
/* p: rest passes banked on arrival. The ladder runs all the way to a year,
   because a streak you cannot see the end of stops being a streak. */
const BADGES = [
  {id:"first",  d:3,   i:"◍", n:"First Rep",     s:"Log one session"},
  {id:"spark",  d:3,   i:"△", n:"Spark",         s:"3-day streak"},
  {id:"week",   d:7,   i:"▣", n:"Week of Iron",  s:"7-day streak",   p:1},
  {id:"fort",   d:14,  i:"◈", n:"Fortnight",     s:"14-day streak",  p:1},
  {id:"habit",  d:21,  i:"◆", n:"Habit",         s:"21-day streak",  p:1},
  {id:"month",  d:30,  i:"⬢", n:"Month of Iron", s:"30-day streak",  p:2},
  {id:"fifty",  d:50,  i:"✦", n:"Half Ton",      s:"50-day streak",  p:2},
  {id:"cent",   d:100, i:"★", n:"Centurion",     s:"100-day streak", p:3},
  {id:"anvil",  d:150, i:"⬟", n:"Anvil",         s:"150-day streak", p:3},
  {id:"forged", d:200, i:"❖", n:"Forged",        s:"200-day streak", p:4},
  {id:"relent", d:250, i:"⧫", n:"Relentless",    s:"250-day streak", p:4},
  {id:"unbrok", d:300, i:"⬣", n:"Unbroken",      s:"300-day streak", p:5},
  {id:"ironman",d:365, i:"⚡", n:"Iron Man",      s:"365 days — one full year", p:7},
  {id:"twoyr",  d:730, i:"☗", n:"Two Years",     s:"730-day streak", p:10}
];
/* The streak multiplier stops climbing at 20 days for most people. Getting past
   a hundred, and then past a year, should be worth more than a badge. */
function streakCap(streak){ return streak >= 365 ? 40 : streak >= 100 ? 30 : 20; }
function rankFor(xp){
  let r = RANKS[0], next = RANKS[1];
  for(let i=0;i<RANKS.length;i++){ if(xp >= RANKS[i].xp){ r = RANKS[i]; next = RANKS[i+1] || null; } }
  const pct = next ? Math.round(100*(xp - r.xp)/(next.xp - r.xp)) : 100;
  return {r, next, pct};
}
function perClass(x){ return x.cls === "comp" ? 15 : x.cls === "acc" ? 11 : x.cls === "core" ? 8 : 9; }
function movePoints(m, effort){
  const em = [0,.85,1,1.15,1.35][effort];
  return Math.round(m.sets * perClass(m.x) * (m.each ? 1.15 : 1) * (m.failure ? 1.25 : 1) * em);
}
function claimedTotal(s){
  /* claimedPts is what actually landed — partial claims bank less than movePoints */
  return s.moves.reduce((a,m) => a + (m.claimed ? (m.claimedPts != null ? m.claimedPts : movePoints(m, s.cfg.effort)) : 0), 0);
}
function scoreSession(s, streak){
  const em = [0,.85,1,1.15,1.35][s.cfg.effort];
  let base = 0;
  for(const m of s.moves) base += m.sets * perClass(m.x) * (m.each ? 1.15 : 1) * (m.failure ? 1.25 : 1);
  if(s.cardio) base += s.cardio.mins * 4 * (s.cardio.style === "intervals" ? 1.25 : s.cardio.style === "finisher" ? 1.3 : 1);
  base *= em;
  const covBonus = Math.round(s.coverage * 0.85);
  const mult = 1 + Math.min(streakCap(streak), streak) * 0.03;
  const total = Math.round((base + covBonus) * mult);
  return {base:Math.round(base), covBonus, mult:+mult.toFixed(2), total};
}
/* ------------------------------------------------------------------ state */
const $  = s => document.querySelector(s);
const $$ = s => Array.from(document.querySelectorAll(s));
const esc = s => String(s).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));

/* --------------------------------------------------------------- calendar */
const dayKey = d => { const z = new Date(d); return z.getFullYear()+"-"+String(z.getMonth()+1).padStart(2,"0")+"-"+String(z.getDate()).padStart(2,"0"); };
function daysApart(a,b){
  const pa = a.split("-").map(Number), pb = b.split("-").map(Number);
  const da = Date.UTC(pa[0],pa[1]-1,pa[2]), db = Date.UTC(pb[0],pb[1]-1,pb[2]);
  return Math.round((db-da)/86400000);
}
function bumpStreak(){
  const today = dayKey(new Date());
  const res = {gained:false, froze:false, reset:false, already:false};
  if(state.lastDay === today){ res.already = true; return res; }
  if(!state.lastDay){ state.streak = 1; }
  else{
    const gap = daysApart(state.lastDay, today);
    if(gap <= 2){ state.streak += 1; res.gained = true; }
    else if(state.freezes > 0 && gap <= 5){ state.freezes -= 1; state.streak += 1; res.froze = true; res.gained = true; }
    else{ state.streak = 1; res.reset = true; }
  }
  state.lastDay = today;
  if(state.streak > 0 && state.streak % 7 === 0) state.freezes += 1;
  return res;
}
function checkBadges(){
  const got = [];
  for(const b of BADGES){
    if(state.badges.includes(b.id)) continue;
    const ok = b.id === "first" ? state.history.length >= 1 : state.streak >= b.d;
    if(ok){
      state.badges.push(b.id); got.push(b);
      if(b.p) state.freezes += b.p;        /* the perk arrives with the badge */
    }
  }
  return got;
}
/* The next rung and how far off it is, for the streak card to point at. */
function nextMilestone(){
  for(const b of BADGES){
    if(b.id === "first" || state.badges.includes(b.id)) continue;
    if(state.streak < b.d) return {b, left:b.d - state.streak};
  }
  return null;
}

/* ---------------------------------------------------------------- profiles
   Progress belongs to a profile, profiles live on this device. There is no
   server behind this app, so "signing in somewhere else" isn't a thing it can
   honestly offer — carrying a profile to another device is an explicit move,
   by code or by backup file. */
const KEY = "fatcamp.v2", OLD_KEY = "fatcamp.v1";
/* Pre-rebrand keys. Everything was stored under liftedai.* until 2026-08-07,
   and reading only the new key would have silently wiped every existing
   install's sessions, streak and settings on first launch after the rename. */
const LEGACY_KEY = "liftedai.v2", LEGACY_OLD_KEY = "liftedai.v1";
const PROFILE_FIELDS = ["name","color","equip","customEquip","gymPhoto","xp","streak",
                        "freezes","lastDay","history","badges","limits","cfg","session",
                        "rewards","redeemed","calView","prs","prPick","unit","lastWeight","load","body",
                        "week","savedSplits","boardScope","offDays","reviewAsk"];
const PROFILE_COLORS = ["var(--p25)","var(--p20)","var(--p15)","var(--p10)"];
/* Movement limitations. Each one names the muscles and patterns to keep out of
   a session, so ticking a box changes what gets generated rather than just
   printing a warning. */
const LIMITS = {
  shoulder: {n:"Shoulder",   pat:["push_v","iso_delt"], mus:["delt_f","delt_s","delt_r"]},
  elbow:    {n:"Elbow",      pat:["iso_arm"],           mus:["triceps","biceps"]},
  wrist:    {n:"Wrist",      pat:[],                    mus:["forearms"], eq:["abwheel"]},
  lowback:  {n:"Lower back", pat:["hinge"],             mus:["lowerback"]},
  knee:     {n:"Knee",       pat:["squat","lunge"],     mus:["quads"]},
  hip:      {n:"Hip",        pat:["hip"],               mus:["glutes","adductors","hipflex"]},
  ankle:    {n:"Ankle",      pat:[],                    mus:["calves","tibialis"]},
  neck:     {n:"Neck",       pat:[],                    mus:["neck","traps"]}
};
/* true when a movement is off the table given the limitations that are on */
function blockedBy(x, limits){
  if(!limits || !limits.length) return false;
  for(const k of limits){
    const L = LIMITS[k]; if(!L) continue;
    if(L.pat.indexOf(x.pat) >= 0) return true;
    if((L.eq || []).some(e => x.eq.indexOf(e) >= 0)) return true;
    /* a primary mover on an injured area is out; a secondary is tolerated */
    if((x.pri || []).some(m => L.mus.indexOf(m) >= 0)) return true;
  }
  return false;
}
const DEFAULT_CFG = {loc:"home", count:5, effort:2, focus:["full"], compounds:[], cardioOn:false, cstyle:"intervals", failureOn:false, preset:null};

function blankProfile(name, color){
  return {name:name||"You", color:color||PROFILE_COLORS[0],
          equip:HOME_DEFAULT.slice(), customEquip:[], gymPhoto:null,
          xp:0, streak:0, freezes:0, lastDay:null, history:[], badges:[], limits:[],
          rewards:[], redeemed:[], calView:"month",
          prs:[], prPick:null, unit:"lb", lastWeight:{}, load:{}, body:{}, week:null, savedSplits:[], boardScope:"global",
          offDays:[],
          cfg:Object.assign({}, DEFAULT_CFG), session:null};
}
let vault = {v:2, active:"p1", theme:null, plan:null, firstUse:null, auth:null, cloud:null, profiles:{}};
let state = blankProfile();

const store = {
  get(k){ try{ return localStorage.getItem(k); }catch(e){ return null; } },
  set(k,v){ try{ localStorage.setItem(k,v); return true; }catch(e){ return false; } }
};
function newId(){ return "p" + Date.now().toString(36) + Math.floor(Math.random()*1e3).toString(36); }

/* ------------------------------------------------------------------ plans
   Trial gives 30 days of everything, measured from first open. Billing is not
   wired up yet — picking a plan applies its limits so each tier can be felt
   out before any store goes live. */
const PLANS = {
  pro:{n:"Pro", price:9.99, moves:10, failure:false, surprise:false, profiles:1, adaptive:false, weekDays:4, splits:1},
  max:{n:"Max", price:14.99, moves:20, failure:true,  surprise:true,  profiles:99, adaptive:true, weekDays:7, splits:99}
};
const FIRST_MONTH = 4.99;              /* everything in Max, for the first month */
/* THE PAYWALL SWITCH. false = personal build: everything unlocked, no StoreKit
   calls, no plans panel, nothing asks for an Apple ID. true = the App Store
   setup exactly as it shipped in 1.3/1.4 (see PAYWALL-RESTORE.md). Flip this one
   line, run npm run sync, push. Nothing else changes. */
const PAYWALL = false;
/* What a session actually costs, from the plan price and the days it allows.
   Computed rather than written down, so the copy cannot drift from the price. */
const WEEKS_PER_MONTH = 52/12;
function perSession(price, daysAWeek){
  const n = daysAWeek * WEEKS_PER_MONTH;
  const c = price / n;
  return {n:Math.round(n), each:c < 1 ? Math.round(c*100) + "¢" : "$" + c.toFixed(2)};
}
function trialDaysLeft(){          /* the paid first month, not a free trial */
  /* Clamped to now, because a start date in the future makes the subtraction
     negative and hands out more than thirty days — a wrong device clock or an
     edited storage entry would otherwise buy an unlimited month. */
  const t0 = Math.min(new Date(vault.firstUse || Date.now()).getTime(), Date.now());
  return Math.max(0, 30 - Math.floor((Date.now() - t0) / 86400000));
}
function tierOf(){
  if(!PAYWALL) return "max";
  if(vault.plan === "pro" || vault.plan === "max") return vault.plan;
  return trialDaysLeft() > 0 ? "trial" : "expired";
}
/* Expired means expired: the sheet stops being generated until there is a
   subscription. Kept as its own predicate rather than folded into limitsOf,
   because limits shape a session and this decides whether there is one at
   all — and limitsOf is read in a dozen places that all still need a sane
   answer while the paywall is up. */
function locked(){ return tierOf() === "expired"; }
function limitsOf(){
  const t = tierOf();
  return (t === "max" || t === "trial") ? PLANS.max : PLANS.pro;  /* expired -> Pro limits */
}

function packSession(sess){
  if(!sess) return null;
  const o = Object.assign({}, sess);
  /* a custom (video) movement is not in the catalogue, so it travels with the
     session as xc — any device or the cloud can rebuild it from that alone */
  o.moves = sess.moves.map(m => { const c = Object.assign({}, m); delete c.x;
    if(m.x && m.x.custom) c.xc = Object.assign({}, m.x);
    return c; });
  if(sess.cardio){ o.cardio = Object.assign({}, sess.cardio, {xid:sess.cardio.x.id}); delete o.cardio.x; }
  return o;
}

function applyPreset(k){
  const p = PRESETS[k];
  const c = state.cfg;
  c.preset = k; c.count = p.count; c.effort = p.effort;
  c.focus = p.focus.slice(); c.cardioOn = p.cardio; c.cstyle = p.cstyle;
  c.failureOn = !!p.failure && limitsOf().failure;
  c.count = Math.min(c.count, limitsOf().moves);
  /* auto-pick the compounds this kit can actually support */
  const avail = availFor(c.loc);
  const bigs = X.filter(x => x.big && x.eq.every(t => avail.includes(t)));
  const seen = new Set(); const chosen = [];
  const order = ["squat","hinge","push_h","pull_h","push_v","pull_v","lunge","hip"];
  for(const pat of order){
    if(chosen.length >= p.comps) break;
    const cands = bigs.filter(x => x.pat === pat && !seen.has(x.id));
    if(cands.length){ const pick = cands[Math.floor(Math.random()*cands.length)]; chosen.push(pick.id); seen.add(pick.id); }
  }
  c.compounds = chosen;
  syncControls(); save();
  toast(p.n+" loaded", "Criteria filled in below. Change anything you like, then forge it.", "");
}

/* -------------------------------------------------------------- the agent
   A sentence in, the Workload above filled in. Deliberately literal: it takes
   what it recognises and leaves the rest of your settings alone, so a half-formed
   request still gets a session rather than an error. */
const ASK_FOCUS = {
  full:      ["full body","fullbody","total body","whole body","everything"],
  push:      ["push","pushing","push day"],
  pull:      ["pull","pulling","pull day"],
  chest:     ["chest","pec","pecs","bench day"],
  back:      ["back","lat","lats","back day"],
  shoulders: ["shoulder","shoulders","delt","delts","overhead day"],
  arms:      ["arm","arms","bicep","biceps","tricep","triceps","curls","gun show"],
  legs:      ["leg","legs","quad","quads","hamstring","hamstrings","glute","glutes",
              "calf","calves","lower body","leg day"],
  posterior: ["posterior","posterior chain","hinge","back side"],
  core:      ["core","abs","oblique","obliques","midsection","six pack","stomach"]
};
const ASK_LIFTS = [
  /* Order is load-bearing: each match is struck out of the sentence before the
     next is tried, so anything containing a shorter lift's name has to come
     first. "hack squat" below "squat" would be heard as a back squat. */
  ["trxrow",      ["trx row","suspension row"]],
  ["trxpush",     ["trx push up","trx push-up","suspension push up"]],
  ["ringrow",     ["ring row"]],
  ["ringdip",     ["ring dip"]],
  ["muscleup",    ["muscle up","muscle-up","muscleup"]],
  ["ropeslam",    ["rope slam","battle rope","battle ropes"]],
  ["ballslam",    ["slam ball","ball slam"]],
  ["landminepress",["landmine press","landmine"]],
  ["sandbagclean",["sandbag clean","sandbag"]],
  ["pistol",      ["pistol squat","pistol"]],
  ["lsit",        ["l-sit","l sit"]],
  ["bearcrawl",   ["bear crawl"]],
  ["boxjump",     ["box jump"]],
  ["hacksquat",   ["hack squat"]],
  ["zercher",     ["zercher"]],
  ["pausesquat",  ["paused squat","pause squat"]],
  ["sumodl",      ["sumo deadlift","sumo"]],
  ["rackpull",    ["rack pull"]],
  ["deficitdl",   ["deficit deadlift"]],
  ["glutehamraise",["glute ham raise","glute-ham raise","ghr"]],
  ["floorpress",  ["floor press"]],
  ["zpress",      ["z press"]],
  ["arnold",      ["arnold press","arnold"]],
  ["pushjerk",    ["push jerk","jerk"]],
  ["tbarrow",     ["t-bar row","t bar row","tbar row"]],
  ["meadowsrow",  ["meadows row"]],
  ["preachercurl",["preacher curl","preacher"]],
  ["ski_int",     ["ski erg","skierg"]],
  ["frontsquat",  ["front squat"]],
  ["bulgarian",   ["bulgarian","split squat"]],
  ["backsquat",   ["back squat","squat","squats","squatting"]],
  ["trapbardl",   ["trap bar"]],
  ["rdl",         ["romanian","rdl","stiff leg","stiff-leg"]],
  ["deadlift",    ["deadlift","deadlifts","deadlifting","pull from the floor"]],
  ["inclinebb",   ["incline bench","incline press","incline"]],
  ["dbbench",     ["dumbbell bench","dumbbell press"]],
  ["bench",       ["bench press","benching","bench"]],
  ["pushpress",   ["push press"]],
  ["ohp",         ["overhead press","military press","strict press","ohp"]],
  ["dbohp",       ["shoulder press","dumbbell shoulder"]],
  ["thruster",    ["thruster","thrusters"]],
  ["pendlay",     ["pendlay"]],
  ["chestrow",    ["chest supported row","chest-supported row","seal row"]],
  ["bbrow",       ["barbell row","bent over row","bent-over row","barbell rows"]],
  ["wpullup",     ["weighted pull"]],
  ["pullup",      ["pull up","pull-up","pullup","pullups","pull ups","pull-ups"]],
  ["chinup",      ["chin up","chin-up","chinup","chinups"]],
  ["latpulldown", ["lat pulldown","pulldown","pull down"]],
  ["dip",         ["dip","dips"]],
  ["hipthrust",   ["hip thrust","hip thrusts"]],
  ["legpress",    ["leg press"]]
];
const ASK_WORDNUM = {one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,
                     nine:9,ten:10,eleven:11,twelve:12,fifteen:15,twenty:20};

/* What the workload says, in one line, so you can check what it heard. */
function askSummary(c){
  const bits = [c.loc === "public" ? "Public gym" : c.loc === "body" ? "Bodyweight" : "Home",
                c.focus.map(k => FOCUS[k].n).join(" + "),
                c.count + " movement" + (c.count === 1 ? "" : "s"),
                EFFORT_N[c.effort]];
  if(c.compounds.length) bits.push(c.compounds.map(id => XMAP[id].n).join(", "));
  if(c.cardioOn) bits.push("+ " + CSTYLE[c.cstyle].n);
  if(c.failureOn) bits.push("to failure");
  return bits.join(" · ");
}

/* Reads a request into state.cfg and returns true if it understood any of it.
   Each ask is the whole request, not an edit of the last one: anything the
   sentence does not mention goes back to its default, so yesterday's bench
   press cannot turn up in today's leg day. Where you train is the exception —
   that is about you, not about this session. */
function askApply(raw){
  const t = " " + String(raw || "").toLowerCase()
    .replace(/[‘’]/g, "'").replace(/[^a-z0-9'\- ]+/g, " ")
    .replace(/\s+/g, " ").trim() + " ";
  if(t.trim().length < 2) return false;
  const q = w => w.replace(/[-\/\\^$*+?.()|[\]{}]/g, "\\$&");
  const rx  = w => new RegExp("(?:^| )" + q(w) + "(?=$| )", "g");
  const rxs = w => new RegExp("(?:^| )" + q(w) + "s?(?=$| )", "g");   /* squat, squats */
  const has = w => rx(w).test(t);

  const before = JSON.parse(JSON.stringify(state.cfg));
  const c = state.cfg;
  let heard = 0;

  /* a named preset is the starting point; otherwise start from the defaults */
  let preset = null;
  if(has("easy day") || has("deload") || has("recovery day") || has("light day")) preset = "easy";
  else if(has("killer") || has("brutal") || has("savage") || has("wreck me") || has("destroy me")) preset = "killer";
  else if(has("just cardio") || has("cardio only") || has("conditioning day")) preset = "cardio";
  else if(has("medium day") || has("normal day") || has("the usual")) preset = "medium";
  if(preset){ applyPreset(preset); heard++; }
  else{
    c.focus = DEFAULT_CFG.focus.slice(); c.count = DEFAULT_CFG.count;
    c.effort = DEFAULT_CFG.effort; c.compounds = [];
    c.cardioOn = DEFAULT_CFG.cardioOn; c.cstyle = DEFAULT_CFG.cstyle;
    c.failureOn = false; c.preset = null;
  }

  /* where */
  if(has("bodyweight") || has("body weight") || has("no equipment") || has("no gear") ||
     has("no gym") || has("nothing") || has("hotel") || has("hotel room") || has("travelling") ||
     has("traveling") || has("on the road") || has("a park") || has("the park") ||
     has("outside") || has("anywhere") || has("calisthenics")){ c.loc = "body"; heard++; }
  else if(has("home") || has("basement") || has("garage") || has("my house") ||
          has("apartment") || has("at home")){ c.loc = "home"; heard++; }
  else if(has("public") || has("commercial") || has("the gym") || has("a gym") ||
          has("planet fitness") || has("my gym") || has("real gym")){ c.loc = "public"; heard++; }
  const avail = availFor(c.loc);

  /* Named lifts are read first and then struck out of the sentence, so that
     "back squat" is not also heard as a back day and "barbell row" is not
     heard as the rowing machine. Whatever is left describes the session. */
  const comps = [];
  let rest = t;
  for(let i=0;i<ASK_LIFTS.length;i++){
    const id = ASK_LIFTS[i][0];
    /* match against what is left, so the specific entries earlier in the list
       take the words first: "bulgarian split squats" is not also a back squat */
    const words = ASK_LIFTS[i][1].filter(w => rxs(w).test(rest));
    if(!words.length) continue;
    words.forEach(w => { rest = rest.replace(rxs(w), " "); });
    const x = XMAP[id];
    if(x && x.eq.every(t2 => avail.indexOf(t2) >= 0) && comps.indexOf(id) < 0) comps.push(id);
  }
  if(comps.length){ c.compounds = comps.slice(0, 4); heard++; }
  const left = w => rx(w).test(rest);

  /* what */
  const foc = [];
  for(const k in ASK_FOCUS) if(ASK_FOCUS[k].some(left)) foc.push(k);
  if(foc.length){ c.focus = foc.indexOf("full") >= 0 ? ["full"] : foc.slice(0, 4); heard++; }

  /* treadmill minutes belong to the treadmill, not to the lifting: "push day,
     20 min treadmill" is a push day plus a 20-minute belt, not a 3-movement day */
  const TREAD = /(\d+)\s*(?:minutes|mins|min)\s+(?:on\s+(?:the\s+|a\s+)?)?(?:treadmill|tread|incline walk)|(?:treadmill|tread|incline walk)\s+(?:for\s+)?(\d+)\s*(?:minutes|mins|min)/;
  const tm = t.match(TREAD);
  const td = tm ? t.replace(tm[0], " ") : t;

  /* how much — a duration is a movement count wearing a disguise */
  let n = null, m;
  if((m = td.match(/(\d+)\s*(?:movements?|moves?|lifts?|exercises?)/))) n = +m[1];
  else if((m = td.match(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|fifteen|twenty)\s+(?:movements?|moves?|lifts?|exercises?)/))) n = ASK_WORDNUM[m[1]];
  else if((m = td.match(/(\d+)\s*(?:min|mins|minutes)/))) n = Math.round(+m[1]/8);
  else if(has("an hour") || has("1 hour") || has("one hour")) n = 7;
  else if(has("half an hour")) n = 4;
  else if(has("two hours") || has("2 hours")) n = 11;
  else if(has("quick") || has("short") || has("in a hurry") || has("no time") || has("rushed")) n = 3;
  else if(has("long session") || has("marathon") || has("all day")) n = 9;
  if(n !== null){ c.count = Math.max(2, Math.min(limitsOf().moves, n)); heard++; }

  /* how hard */
  let e = null;
  if(has("deload") || has("easy") || has("light") || has("recovery") || has("gentle") ||
     has("sore") || has("tired") || has("beat up") || has("hungover")) e = 1;
  if(has("medium") || has("moderate") || has("normal") || has("standard")) e = 2;
  if(has("hard") || has("heavy") || has("tough") || has("push me") || has("intense")) e = 3;
  if(has("killer") || has("brutal") || has("savage") || has("max out") || has("destroy") ||
     has("wreck") || has("insane") || has("all out") || has("hardest")) e = 4;
  if(e !== null){ c.effort = e; heard++; }

  /* to failure */
  if(has("to failure") || has("failure") || has("amrap") ||
     has("until i can't") || has("till i can't")){ c.failureOn = limitsOf().failure; heard++; }
  if(has("no failure") || has("not to failure")){ c.failureOn = false; heard++; }

  /* conditioning */
  const cardioWords = ["cardio","conditioning","run","running","jog","row","rowing","bike",
    "biking","sprint","sprints","hiit","interval","intervals","finisher","jump rope",
    "skipping","burpees","engine","zone 2","zone two","steady state"];
  if(tm || has("treadmill") || has("incline walk") || has("tread")){
    c.cardioOn = true; c.cstyle = "treadmill"; heard++;
    if(tm) c.tmins = Math.max(5, Math.min(120, +(tm[1] || tm[2])));
  }
  else if(cardioWords.some(left)){
    c.cardioOn = true; heard++;
    if(has("hiit") || has("interval") || has("intervals") || has("sprint") || has("sprints")) c.cstyle = "intervals";
    else if(has("finisher") || has("burpees")) c.cstyle = "finisher";
    else if(has("steady") || has("jog") || has("zone 2") || has("zone two") || has("easy run")) c.cstyle = "steady";
  }
  if(has("no cardio") || has("skip cardio") || has("without cardio") ||
     has("weights only") || has("lifting only")){ c.cardioOn = false; heard++; }

  if(!heard){ state.cfg = before; return false; }

  c.compounds = c.compounds.filter(id => XMAP[id].eq.every(q => avail.indexOf(q) >= 0));
  c.count = Math.min(Math.max(c.count, c.compounds.length), limitsOf().moves);
  if(c.failureOn && !limitsOf().failure) c.failureOn = false;
  if(heard > (preset ? 1 : 0)) c.preset = null;

  syncControls(); save();
  return true;
}


function repsLabel(m){
  if(m.failure) return "AMRAP";
  return m.unit === "sec" ? m.reps : m.reps + (m.each ? " each" : "");
}

function cardioTarget(c){ return c.style === "treadmill" ? Math.max(1, c.mins - 5) : c.mins; }
function watchPayload(s){
  if(!s) return "";
  return JSON.stringify({
    sid:String(s.date), title:s.title, effort:s.cfg.effort|0, unit:state.unit || "lb",
    streak:state.streak|0, points:scoreSession(s, state.streak).total,
    moves:s.moves.map((m, i) => ({i, n:m.x.n, sets:m.sets, reps:String(repsLabel(m)), rest:m.rest|0,
      done:Array.from({length:m.sets}, (_, k) => !!m.doneSets[k]), claimed:!!m.claimed,
      failure:!!m.failure, weight:String(m.weight || ""), cls:m.x.cls, a:m.x.arch || ""})),
    cardio:s.cardio ? {n:s.cardio.x.n, style:s.cardio.style, styleName:s.cardio.styleName,
      mins:s.cardio.mins|0, target:cardioTarget(s.cardio), segs:s.cardio.segs || [],
      done:!!s.cardio.done, doneMins:s.cardio.doneMins != null ? s.cardio.doneMins : null} : null
  });
}


/** text + the person's saved kit and history in; a phone session and the watch's copy out. */
export function forge({ text, profile = {}, seed }) {
  state = blankProfile();
  if (Array.isArray(profile.equip) && profile.equip.length) state.equip = profile.equip.filter((e) => typeof e === "string");
  if (Array.isArray(profile.limits)) state.limits = profile.limits.filter((e) => typeof e === "string");
  if (Array.isArray(profile.history)) state.history = profile.history.slice(0, 14).map((h) => ({ mids: Array.isArray(h.mids) ? h.mids : [] }));
  if (typeof profile.unit === "string") state.unit = profile.unit;
  state.streak = profile.streak | 0;
  state.cfg = JSON.parse(JSON.stringify(DEFAULT_CFG));
  if (["home", "public", "body"].includes(profile.loc)) state.cfg.loc = profile.loc;
  const heard = askApply(String(text || ""));
  const cfg = JSON.parse(JSON.stringify(state.cfg));
  cfg.seed = Number.isFinite(seed) ? seed : (Math.random() * 1e9) | 0;
  const s = generate(cfg);
  return { heard, summary: askSummary(state.cfg), packed: packSession(s), watch: watchPayload(s) };
}
